using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using Newtonsoft.Json.Linq;
using UnityEngine;

namespace DungeonContract.Editor
{
    public static class DcP4Checks
    {
        private static JObject parameters;
        private static JObject geometry;
        private static readonly List<string> passed=new List<string>();
        private static DcP1World World(int count=1,string loadout="ranger",int seed=20261012)=>new DcP1World(new JObject{["parameters"]=parameters,["p1_world"]=geometry,["p2_stage"]=true,["p3_stage"]=true,["p4_stage"]=true,["weapon_stage"]=true,["seed"]=seed,["run_id"]="p4_model",["members"]=new JArray(Enumerable.Range(0,count).Select(index=>new JObject{["player_id"]=(index+1).ToString(),["slot"]=index,["loadout_id"]=loadout}))});
        private static void Require(bool value,string name){if(!value)throw new InvalidOperationException("P4 "+name);}
        private static void Case(string name,Action action){action();passed.Add(name);}
        private static JToken Own(DcP1World world,int index=0)=>world.Snapshot()["players"][index];
        private static void Clear(DcP1World world,int room,long game=33){var state=world.Capture();state["rooms"][room]["Status"]="cleared";world.Restore(state);world.Tick(game);}
        private static DcP1Input Choice(DcP1World world,int option=0,int player=0)
        {
            var own=Own(world,player);
            return new DcP1Input{Sequence=1,WeaponID=(string)own["active_weapon_id"],WeaponRevision=(uint)own["weapon_revision"],ChoiceNode=(int)own["choice_node"],ChoiceRevision=(int)own["choice_revision"],ChoiceHash=(string)own["choice_hash"],ChoiceOption=(string)own["candidates"][option]};
        }
        private static DcP1World Module(string module,string loadout="ranger")
        {
            for(var seed=0;seed<128;seed++){var world=World(1,loadout,seed);Clear(world,1);var candidates=(JArray)Own(world)["candidates"];var index=candidates.Select((item,position)=>(id:(string)item,position)).Where(item=>item.id==module).Select(item=>item.position).DefaultIfEmpty(-1).First();if(index>=0){Require(world.Action("1","growth_choice",Choice(world,index)),"install "+module);return world;}}
            throw new InvalidOperationException("module candidate absent "+module);
        }
        public static void Regression(){DcP3Checks.Regression();Run();}
        private static DcP1World EffectWorld(string kit,params string[] modules)
        {
            var world=new DcP1World(new JObject{["parameters"]=parameters,["p1_world"]=geometry,["practice"]=true,["p2_stage"]=true,["p3_stage"]=true,["p4_stage"]=true,["weapon_stage"]=true,["seed"]=20261012,["run_id"]="p4_effect_fixture",["members"]=new JArray(new JObject{["player_id"]="1",["slot"]=0,["loadout_id"]=kit})});
            foreach(var module in modules)world.InstallForCheck("1",module);
            var state=world.Capture();state["enemies"]=new JArray(new JObject{["ID"]="fx_target",["Kind"]="guard",["Room"]=0,["Position"]=new JObject{["x"]=5,["y"]=6},["Health"]=1000,["Maximum"]=1000,["AttackAt"]=999999,["ReadyAt"]=999999});world.Restore(state);world.Tick(0);return world;
        }
        private static DcP1Input Weapon(DcP1World world)=>new DcP1Input{WeaponID=world.ActiveWeapon("1"),WeaponRevision=world.WeaponRevision("1")};
        public static void Run()
        {
            parameters=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/config/parameters-v4-p2-1.json")));geometry=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/config/world-v4-p4.json")));passed.Clear();
            Case("three independent nodes never freeze combat or mainline",()=>{var world=World(2);Clear(world,1);Clear(world,3,66);Clear(world,4,99);Require((int)world.Snapshot()["safe_node"]==-1&&((JArray)Own(world)["growth"]).Count==3&&((JArray)Own(world,1)["growth"]).Count==3,"nodes");});
            Case("manual choice immediately installs only owner",()=>{var world=World(2);Clear(world,1);var intent=Choice(world);Require(world.Action("1","growth_choice",intent),"accept");Require(((JArray)Own(world)["upgrades"]).Count==1&&((JArray)Own(world,1)["upgrades"]).Count==0,"independent");});
            Case("stale revision and hash reject without installation",()=>{var world=World();Clear(world,1);var intent=Choice(world);intent.ChoiceRevision++;Require(!world.Action("1","growth_choice",intent)&&((JArray)Own(world)["upgrades"]).Count==0,"stale");intent=Choice(world);intent.ChoiceHash=new string('0',64);Require(!world.Action("1","growth_choice",intent),"hash");});
            Case("oldest pending first and later candidate revisions",()=>{var world=World();Clear(world,1);Clear(world,3,66);var prior=Own(world)["growth"][1].DeepClone();var illegal=Choice(world);illegal.ChoiceNode=1;Require(!world.Action("1","growth_choice",illegal),"out of order");Require(world.Action("1","growth_choice",Choice(world)),"first");Require((int)Own(world)["choice_node"]==1&&!((JArray)Own(world)["candidates"]).Any(item=>(string)item==(string)Own(world)["upgrades"][0]),"refresh");});
            Case("default selects first at 60 game seconds not earlier",()=>{var world=World();Clear(world,1);var expected=(string)Own(world)["candidates"][0];world.Tick(60032);Require(((JArray)Own(world)["upgrades"]).Count==0,"early");var facts=world.Tick(60033);Require((string)Own(world)["upgrades"][0]==expected&&facts.Count(item=>(string)item["kind"]=="growth_choice")==1,"default");world.Tick(60066);Require(((JArray)Own(world)["upgrades"]).Count==1,"duplicate");});
            Case("deadline rejects manual then applies automatic",()=>{var world=World();Clear(world,1);var intent=Choice(world);world.AdvanceTime(60033);Require(!world.Action("1","growth_choice",intent),"late manual");world.Tick(60033);Require((bool)Own(world)["growth"][0]["automatic"],"default missing");});
            Case("disconnect defaults while permanent exit never installs",()=>{var world=World(2);Clear(world,1);world.Presence("1",false);world.Leave("2");world.Tick(60033);Require(((JArray)Own(world)["upgrades"]).Count==1&&((JArray)Own(world,1)["upgrades"]).Count==0,"lifecycle");});
            Case("downed choice installs vitality without revival",()=>{var world=World(2);Clear(world,1);var state=world.Capture();state["players"][0]["Health"]=0;state["players"][0]["Life"]="downed";state["players"][0]["DownedUntil"]=10000;world.Restore(state);Require(world.Action("1","growth_choice",Choice(world))&&(int)Own(world)["health"]==0,"revived");});
            Case("checkpoint restores exact candidates deadlines and installed effects",()=>{var world=World();Clear(world,1);Clear(world,3,66);world.Action("1","growth_choice",Choice(world));var before=world.Snapshot();var checkpoint=world.Capture();world.Tick(61000);world.Restore(checkpoint);Require(JToken.DeepEquals(before,world.Snapshot()),"restore");});
            Case("technical wait overdue defaults without attack catchup",()=>{var world=World();Clear(world,1);world.TechnicalWait(true,33);world.TechnicalWait(false,61000);world.Tick(61000);Require(((JArray)Own(world)["upgrades"]).Count==1,"wait deadline");});
            Case("all legal three-choice paths retain three distinct candidates",()=>{foreach(var kit in new[]{"ranger","runesmith"})for(var first=0;first<3;first++)for(var second=0;second<3;second++)for(var third=0;third<3;third++){var world=World(1,kit);var options=new[]{first,second,third};var nodes=new[]{1,3,4};for(var index=0;index<3;index++){Clear(world,nodes[index],33+index*33);var candidates=(JArray)Own(world)["candidates"];Require(candidates.Count==3&&candidates.Select(item=>(string)item).Distinct().Count()==3,"not three");Require(world.Action("1","growth_choice",Choice(world,options[index])),"history");}Require(((JArray)Own(world)["upgrades"]).Count==3,"third use");}});
            Case("all ten modules use real growth installation",()=>{foreach(var module in (JArray)parameters["growth"]){var kit=(string)module["scope"]=="runesmith"?"runesmith":"ranger";var world=Module((string)module["id"],kit);Require(((JArray)Own(world)["upgrades"]).Any(item=>(string)item==(string)module["id"]),"missing module");}});
            Case("vitality raises cap and restores at most twenty",()=>{var world=Module("vitality");Require((int)Own(world)["max_health"]==120&&(int)Own(world)["health"]==120,"cap");});
            Case("swift changes authoritative Space cooldown",()=>{var world=Module("swift");Require(world.Action("1","dodge",new DcP1Input{WeaponID=world.ActiveWeapon("1"),WeaponRevision=1}),"dodge");Require((long)Own(world)["dodge_remaining_ms"]==2400,"swift absent");});
            Case("tension changes loaded capacity without free ammunition",()=>{var world=Module("ranger_tension");Require((int)Own(world)["magazine_max"]==10&&(int)Own(world)["magazine"]==8,"ammo minted");});
            Case("cleared rune reward survives walking then triggers in later combat",()=>{var world=World();var state=world.Capture();state["rooms"][6]["Status"]="active";state["rooms"][6]["Wave"]=1;world.Restore(state);world.Tick(33);Require((int)Own(world)["pending_shield"]==15&&(int)Own(world)["shield"]==0,"early shield");state=world.Capture();state["players"][0]["Room"]=3;state["rooms"][3]["Status"]="active";state["rooms"][3]["Mechanism"]=false;world.Restore(state);world.Tick(66);Require((int)Own(world)["pending_shield"]==0&&(int)Own(world)["shield"]==15,"trigger");});
            Case("short disconnect retains pending shield until a connected combat tick",()=>{var world=World(2);var state=world.Capture();state["players"][0]["Room"]=3;state["players"][0]["PendingShield"]=15;state["rooms"][3]["Status"]="active";state["rooms"][3]["Mechanism"]=false;world.Restore(state);world.Presence("1",false);world.Tick(33);Require((int)Own(world)["pending_shield"]==15&&(int)Own(world)["shield"]==0,"offline shield consumed");world.Reconnect("1");world.Tick(66);Require((int)Own(world)["pending_shield"]==0&&(int)Own(world)["shield"]==15,"connected shield did not trigger");});
            Case("supply is personal and full health never consumes",()=>{var world=World(2);var state=world.Capture();state["rooms"][7]["Status"]="cleared";foreach(var player in state["players"]){player["Room"]=7;player["Position"]=new JObject{["x"]=15,["y"]=6};}world.Restore(state);var input=new DcP1Input{Interact=true,WeaponRevision=1,WeaponID=world.ActiveWeapon("1")};world.Input("1",input);world.Tick(33);Require(!(bool)Own(world)["branch_supply_used"],"full consumed");state=world.Capture();state["players"][0]["Health"]=50;world.Restore(state);world.Input("1",input);world.Tick(66);Require((int)Own(world)["health"]==80&&(bool)Own(world)["branch_supply_used"]&&!(bool)Own(world,1)["branch_supply_used"],"shared consumption");});
            Case("supply rejects same-frame skill and dodge without consuming",()=>{var world=World();var state=world.Capture();state["rooms"][7]["Status"]="cleared";state["players"][0]["Room"]=7;state["players"][0]["Health"]=50;state["players"][0]["Position"]=new JObject{["x"]=15,["y"]=6};world.Restore(state);var input=Weapon(world);input.Interact=true;input.ActionSequence=1;world.QueueAction("1","ability_secondary",input,"same_frame_supply_cast");world.Input("1",input);world.Tick(33);Require(!(bool)Own(world)["branch_supply_used"]&&(int)Own(world)["health"]==50,"skill supply");state=world.Capture();state["players"][0]["DodgeUntil"]=1000;state["players"][0]["DodgeDirection"]=new JObject{["x"]=1,["y"]=0};world.Restore(state);world.Input("1",input);world.Tick(66);Require(!(bool)Own(world)["branch_supply_used"],"dodge supply");});
            Case("frozen count scales population and health",()=>{for(var count=1;count<=4;count++){var world=World(count);var state=world.Capture();state["players"][0]["Room"]=1;state["players"][0]["Position"]=new JObject{["x"]=3,["y"]=9};world.Restore(state);world.Tick(0);world.Tick(2001);var expected=new[]{10,14,18,22}[count-1];Require((int)world.Snapshot()["rooms"][1]["pending"]+((JArray)world.Snapshot()["spawn_reservations"]).Count==expected,"count rounding");}});
            Case("runtime snapshot equals full recovery snapshot including growth",()=>{var world=World(4);Clear(world,1);world.Action("1","growth_choice",Choice(world));var expected=JObject.Parse(world.Snapshot().ToString());var actual=JObject.Parse(world.RuntimeSnapshot().ToString());Require(JToken.DeepEquals(expected,actual),"snapshot mismatch "+string.Join(",",expected.Properties().Where(item=>!JToken.DeepEquals(item.Value,actual[item.Name])).Select(item=>item.Name)));});
            Case("other players cannot read private candidates",()=>{var world=World(2);Clear(world,1);var value=DcP21Interest.ForPlayer(world.Snapshot(),"1");Require(((JArray)value["players"][1]["candidates"]).Count==0&&((JArray)value["players"][1]["growth"]).Count==0,"candidate privacy");});
            Case("ChoiceOverlay has independent real Input System bindings",()=>{using var controls=new DcP1Controls(true);Require(controls.Asset.FindAction("ChoiceOverlay/Toggle")!=null&&Enumerable.Range(1,3).All(index=>controls.Asset.FindAction("ChoiceOverlay/Select"+index)!=null),"empty input context");});
            Case("battle manifest exposes only owner task remainder without mutating authority",()=>{var manifest=new JObject{["task_requirements"]=new JObject{["1"]=new JObject{["damage:"]=100},["2"]=new JObject{["kill:"]=64}},["p1_world_hash"]="frozen_geometry"};var visible=DcP21Interest.ManifestForPlayer(manifest,"1");Require(((JObject)visible["task_requirements"]).Properties().Select(item=>item.Name).SequenceEqual(new[]{"1"})&&((JObject)manifest["task_requirements"]).Count==2&&(string)visible["p1_world_hash"]=="frozen_geometry","manifest privacy");Require(((JObject)DcP21Interest.ManifestForPlayer(manifest,"3")["task_requirements"]).Count==0,"foreign default");});
            Case("CSharp and Go candidate canonical golden vector",()=>{var world=World();Clear(world,1);Require(string.Join("|",((JArray)Own(world)["candidates"]).Select(item=>(string)item))=="swift|ward|ranger_fan"&&(string)Own(world)["choice_hash"]=="2dc7223035962a95c8cb8e88c08ad10624bdf29a836db674261fc9a99b793634","cross language candidates");});
            Case("fan emits three reduced damage projectiles",()=>{var world=EffectWorld("ranger","ranger_fan");world.Action("1","attack_press",Weapon(world));world.Tick(33);var shots=(JArray)world.Capture()["projectiles"];Require(shots.Count==3&&shots.All(item=>(int)item["Damage"]==7),"fan effect");});
            Case("frost slows real normal and Boss hits by distinct factors",()=>{foreach(var kind in new[]{"guard","boss"}){var world=EffectWorld("ranger","frost");var state=world.Capture();state["enemies"][0]["Kind"]=kind;world.Restore(state);world.Action("1","attack_press",Weapon(world));for(var game=33;game<=165;game+=33)world.Tick(game);Require(Math.Abs((float)world.Capture()["enemies"][0]["SlowFactor"]-(kind=="boss"?0.95f:0.8f))<0.001f,"frost "+kind);}});
            Case("ward requires successful skill and never stacks shield",()=>{var world=EffectWorld("ranger","ward");Require(world.Action("1","ability_secondary",Weapon(world))&&(int)Own(world)["shield"]==15,"ward grant");Require(!world.Action("1","ability_secondary",Weapon(world))&&(int)Own(world)["shield"]==15,"failed stacks");});
            Case("twin and heavy multiply each emitted turret shot with floor",()=>{var world=EffectWorld("runesmith","runesmith_twin","runesmith_heavy");Require(world.Action("1","ability_primary",Weapon(world)),"deploy");world.Tick(33);var shots=(JArray)world.Capture()["projectiles"];Require(shots.Count==2&&shots.All(item=>(int)item["Damage"]==13),"twin heavy floor");});
            Case("absent branch and connector cannot be entered",()=>{var variant=(JObject)geometry.DeepClone();variant["rooms"][6]["exists"]=false;variant["rooms"][13]["exists"]=false;var world=new DcP1World(new JObject{["parameters"]=parameters,["p1_world"]=variant,["p4_stage"]=true,["p3_stage"]=true,["p2_stage"]=true,["weapon_stage"]=true,["seed"]=1,["members"]=new JArray(new JObject{["player_id"]="1",["slot"]=0,["loadout_id"]="ranger"})});Require(!(bool)world.Snapshot()["rooms"][6]["exists"]&&!(bool)world.Snapshot()["rooms"][13]["exists"],"branch restored");});
            Case("control fence retains confirmed growth and removes departed unconfirmed choice",()=>{var world=World(2);var state=world.Capture();state["rooms"][1]["Status"]="cleared";world.Restore(state);var holder=new GameObject("P4 growth replay fixture");try{var runtime=holder.AddComponent<DcP0V3>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(DcP0V3).GetField("p1World",flags).SetValue(runtime,world);var tick=typeof(DcP0V3).GetMethod("TickP3",flags);for(var frame=1;frame<=12;frame++){if(frame==2||frame==9){var player=frame==2?0:1;var input=Choice(world,0,player);input.ActionSequence=1;world.QueueAction((player+1).ToString(),"growth_choice",input,"growth_replay_"+player);}tick.Invoke(runtime,new object[]{frame*33L,frame*33L});}typeof(DcP0V3).GetField("p3ConfirmedTick",flags).SetValue(runtime,8L);((HashSet<string>)typeof(DcP0V3).GetField("p3Left",flags).GetValue(runtime)).Add("2");typeof(DcP0V3).GetMethod("RebaseP3",flags).Invoke(runtime,null);Require(((JArray)Own(world)["upgrades"]).Count==1&&((JArray)Own(world,1)["upgrades"]).Count==0&&(bool)Own(world,1)["left"],"growth replay prefix");}finally{UnityEngine.Object.DestroyImmediate(holder);}});
            Case("LAN explicit addresses and admissions stay pinned to selected host",()=>{foreach(var host in new[]{"127.0.0.1","127.0.0.2","26.1.2.3","192.168.1.20","10.1.2.3","172.16.1.2"}){Require(DcLanAddress.Validate(host)==host,"valid host");DcLanAddress.ValidateAdmission(host,host+":12777");}foreach(var host in new[]{"0.0.0.0","8.8.8.8","localhost","http://26.1.2.3","26.1.2.3:12777","::1"," 26.1.2.3","172.32.1.2"}){var rejected=false;try{DcLanAddress.Validate(host);}catch(InvalidDataException){rejected=true;}Require(rejected,"unsafe host "+host);}var mismatch=false;try{DcLanAddress.ValidateAdmission("26.1.2.3","26.9.9.9:12777");}catch(InvalidDataException){mismatch=true;}Require(mismatch,"endpoint redirect");});
            File.WriteAllText((DcBootstrap.DemoEvidenceRoot+"/")+(DcV6Profile.Active?"v6-regression-":"")+"p4-model.json",new JObject{["scope"]="P4_model_modified_state_fixtures",["passed"]=passed.Count,["cases"]=new JArray(passed),["real_udp"]=false,["human"]=false}.ToString());Debug.Log("DC P4 model passed "+passed.Count);
        }
    }
}
